select * from (values
('Midjourney','텍스트와 참조 이미지로 고품질 이미지·영상을 만드는 생성형 AI #이미지생성 #AI영상 #스타일 #크리에이티브','Midjourney는 웹과 Discord에서 텍스트·이미지 프롬프트를 이용해 이미지와 짧은 영상을 생성·변형하는 시각 생성 AI입니다. 모든 사용 플랜은 유료 구독입니다.','https://www.midjourney.com/','https://www.midjourney.com/favicon.ico','Paid','$10','Basic 월 $10 · 연간 결제 월 환산 $8',array['Basic $10, Standard $30, Pro $60, Mega $120/월입니다.','Standard 이상은 Relax Mode 이미지 생성, Pro 이상은 Relax Mode 영상과 Stealth Mode를 제공합니다.','연간 선결제는 월 환산 가격이 20% 낮습니다.'],'USD','https://docs.midjourney.com/hc/en-us/articles/27870484040333-Comparing-Midjourney-Plans',now(),'None',true,false,false,null,'Native','specialized',array['AI 이미지 생성','참조 이미지 변형','AI 영상 생성'],array['스타일 제어','Relax Mode','비공개 생성'],array['높은 품질의 스타일 이미지','다양한 참조·변형 제어','유료 플랜의 일반 상업 이용 조건'],array['콘셉트 아트와 광고 시안을 만드는 사용자','강한 미적 스타일이 필요한 창작자'],array['무료 플랜이 없습니다.','기본 생성물은 공개될 수 있고 비공개 모드는 Pro 이상입니다.','연 매출 100만 달러 초과 기업은 Pro 이상 조건을 확인해야 합니다.','공식 공개 API는 제공하지 않습니다.'],array['https://docs.midjourney.com/hc/en-us/articles/33329261836941-Getting-Started-Guide','https://docs.midjourney.com/hc/en-us/articles/27870484040333-Comparing-Midjourney-Plans'],now(),now()),
('Adobe Firefly','이미지·영상·오디오·벡터 생성과 편집을 Adobe 앱에 연결하는 AI #이미지생성 #AI영상 #오디오 #디자인','Adobe Firefly는 이미지·영상·오디오·벡터 생성과 Generative Fill, 번역 등을 제공하고 Photoshop·Illustrator·Premiere 등과 연결되는 생성형 AI 플랫폼입니다.','https://firefly.adobe.com/','https://www.adobe.com/favicon.ico','Freemium','$0','무료 일일 생성 · Standard 월 $9.99부터',array['무료 플랜은 제한된 일일 이미지·영상·오디오 생성을 제공합니다.','Standard $9.99/월은 월 2,000 생성 크레딧을 제공합니다.','프리미엄 영상·오디오와 파트너 모델은 생성 크레딧을 사용합니다.'],'USD','https://www.adobe.com/products/firefly/plans.html',now(),'Full Support',true,false,true,'https://developer.adobe.com/firefly-services/docs/firefly-api/','Native','specialized',array['이미지·벡터 생성','영상·오디오 생성','생성형 편집'],array['Adobe 앱 연동','콘텐츠 자격증명','기업 API'],array['Adobe 제작 도구와 연결','Firefly 모델 출력의 상업 이용 안내','Content Credentials 자동 부착'],array['Adobe 앱을 쓰는 디자이너','상업용 시각 자료를 제작하는 팀'],array['파트너 모델 출력은 해당 모델의 조건을 별도로 확인해야 합니다.','월간 생성 크레딧은 이월되지 않습니다.','API 상품과 일반 구독 범위가 다를 수 있습니다.'],array['https://www.adobe.com/products/firefly/plans.html','https://developer.adobe.com/firefly-services/docs/firefly-api/'],now(),now()),
('Leonardo.Ai','이미지·영상·3D 에셋을 생성·편집하고 API로 연결하는 AI 스튜디오 #이미지생성 #AI영상 #3D #API','Leonardo.Ai는 이미지·영상·오디오·3D 생성, 업스케일, 사용자 모델과 시각적 워크플로를 제공하는 크리에이티브 플랫폼이며 별도 생성 API를 운영합니다.','https://leonardo.ai/','https://leonardo.ai/favicon.ico','Freemium','$0','무료 일 150토큰 · Essential 월 $12부터',array['Free는 매일 150 Fast Tokens와 공개 생성을 제공합니다.','Essential은 월 $12에 8,500 Fast Tokens와 비공개 생성을 제공합니다.','API 계정은 웹 구독과 별도이며 신규 API 계정에 $5 시험 크레딧을 안내합니다.'],'USD','https://leonardo.ai/pricing',now(),'None',true,false,true,'https://docs.leonardo.ai/','Native','specialized',array['이미지·영상 생성','3D·업스케일','사용자 모델'],array['시각적 워크플로','Blueprint','생성 API'],array['여러 미디어 생성 기능 통합','무료 일일 토큰','웹 설정을 API 코드로 내보내기'],array['게임·제품·광고 에셋 제작자','생성 기능을 API로 연동하려는 개발자'],array['무료 생성은 공개됩니다.','웹 구독과 API 크레딧은 별도입니다.','출력 권리는 플랜과 약관을 확인해야 합니다.'],array['https://leonardo.ai/pricing','https://leonardo.ai/api','https://docs.leonardo.ai/v1.0/docs/getting-started'],now(),now()),
('Ideogram','이미지 속 글자 표현과 디자인 생성에 강점을 둔 이미지 AI #이미지생성 #텍스트렌더링 #디자인 #로고','Ideogram은 텍스트 프롬프트와 참조 이미지를 이용해 타이포그래피, 포스터, 로고와 일반 이미지를 생성하고 편집하는 AI 이미지 도구입니다.','https://ideogram.ai/','https://ideogram.ai/favicon.ico','Freemium','$0','무료 생성 제공 · 유료 구독에서 우선 크레딧·비공개 기능 확대',array['무료 플랜은 제한된 생성과 공개 결과를 제공합니다.','유료 플랜은 우선 크레딧, 편집·참조 기능과 비공개 생성을 확대합니다.','AI 편집과 Image Reference는 우선 크레딧이 필요할 수 있습니다.'],'USD','https://ideogram.ai/pricing',now(),'None',true,false,true,'https://developer.ideogram.ai/','Native','specialized',array['AI 이미지 생성','이미지 내 텍스트','이미지 편집'],array['스타일 참조','비공개 생성','API'],array['포스터·로고의 텍스트 표현','간단한 디자인 시안 생성','개발자용 이미지 생성 API'],array['타이포그래피가 중요한 디자이너','포스터·썸네일·로고를 만드는 사용자'],array['무료 생성물은 공개될 수 있습니다.','편집·참조 기능은 플랜과 크레딧 조건이 다릅니다.','상표와 폰트 권리를 별도로 확인해야 합니다.'],array['https://ideogram.ai/','https://ideogram.ai/pricing','https://docs.ideogram.ai/plans-and-pricing/available-plans'],now(),now()),
('Recraft','브랜드 그래픽·벡터·아이콘과 이미지를 생성·편집하는 디자인 AI #벡터생성 #이미지생성 #브랜딩 #디자인','Recraft는 래스터 이미지와 벡터, 아이콘, 목업을 생성하고 스타일 일관성·배경 제거·인페인팅을 지원하는 디자인 AI이며 공식 API를 제공합니다.','https://www.recraft.ai/','https://www.recraft.ai/favicon.ico','Freemium','$0','무료 일 30크레딧 · Basic 월 $12부터',array['Free는 매일 30크레딧을 제공하고 생성물은 공개됩니다.','Basic은 월 $12에 1,000크레딧과 비공개·상업 이용 권리를 제공합니다.','API는 요청별 크레딧 방식으로 별도 과금됩니다.'],'USD','https://www.recraft.ai/pricing',now(),'None',true,false,true,'https://www.recraft.ai/docs/api-reference','Native','specialized',array['벡터·이미지 생성','브랜드 스타일','이미지 편집'],array['배경 제거','목업','API'],array['편집 가능한 벡터 생성','브랜드 스타일 일관성','디자인 생성 공식 API'],array['브랜드·아이콘·마케팅 그래픽 제작자','벡터 생성이 필요한 디자이너'],array['무료 생성물은 Recraft 소유이며 상업 이용할 수 없습니다.','무료 결과는 공개 갤러리에 표시될 수 있습니다.','상업 이용과 소유권은 유료 생성물에 적용됩니다.'],array['https://www.recraft.ai/pricing','https://www.recraft.ai/docs/plans-and-billing/free-plan','https://www.recraft.ai/docs/plans-and-billing/paid-plans'],now(),now()),
('HeyGen','AI 아바타·음성으로 다국어 발표·마케팅 영상을 제작하고 번역하는 도구 #AI아바타 #영상번역 #더빙 #AI영상','HeyGen은 스크립트에서 AI 아바타 영상을 만들고 사용자 디지털 트윈, 음성 복제, 립싱크 번역과 영상 에이전트를 제공하는 AI 영상 플랫폼입니다.','https://www.heygen.com/','https://www.heygen.com/favicon.ico','Freemium','$0','무료 월 최대 3개 영상 · Creator 월 $29',array['Free는 지역에 따라 월 1~3개, 영상당 최대 1분을 제공합니다.','Creator는 월 $29에 600크레딧과 1080p·워터마크 제거를 제공합니다.','API는 일반 구독과 별도 종량제이며 무료 API 크레딧은 제공하지 않습니다.'],'USD','https://www.heygen.com/pricing',now(),'Full Support',true,false,true,'https://docs.heygen.com/','Native','specialized',array['AI 아바타 영상','영상 번역·더빙','디지털 트윈'],array['음성 복제','Video Agent','API'],array['카메라 없이 발표 영상 제작','다국어 번역과 립싱크','아바타 영상 API'],array['교육·영업·마케팅 영상 제작자','다국어 현지화가 필요한 팀'],array['무료 영상 수는 지역에 따라 달라질 수 있습니다.','디지털 트윈과 음성 복제에는 당사자 동의가 필요합니다.','일반 플랜·API·LiveAvatar 과금은 별도입니다.'],array['https://www.heygen.com/pricing','https://help.heygen.com/en/articles/15125761-heygen-credit-based-pricing-plans-explained','https://help.heygen.com/en/articles/10060327-heygen-api-pricing-explained'],now(),now()),
('Synthesia','스크립트로 다국어 AI 아바타 교육·기업 영상을 만드는 도구 #AI아바타 #교육영상 #더빙 #기업영상','Synthesia는 스크립트, 문서와 슬라이드에서 AI 아바타 발표 영상을 만들고 다국어 음성·더빙·브랜드 협업 기능을 제공하는 기업용 AI 영상 도구입니다.','https://www.synthesia.io/','https://www.synthesia.io/favicon.ico','Freemium','$0','Basic 무료 월 10분 · Starter 월 $29',array['Basic은 월 1,200크레딧으로 최대 10분 영상과 제한된 아바타를 제공합니다.','Starter는 월 $29이며 다운로드·로고 제거·125개 이상 아바타를 제공합니다.','Enterprise는 맞춤 가격과 조직·보안·확장 기능을 제공합니다.'],'USD','https://www.synthesia.io/pricing',now(),'Full Support',true,false,true,'https://docs.synthesia.io/','Native','specialized',array['AI 아바타 영상','다국어 내레이션','AI 더빙'],array['문서 기반 영상','브랜드 템플릿','기업 API'],array['촬영 없이 교육·설명 영상 제작','기업용 협업과 브랜드 관리','다국어 아바타·더빙'],array['교육·온보딩 영상을 만드는 조직','글로벌 설명 영상을 제작하는 팀'],array['아바타·다운로드 범위는 플랜별로 다릅니다.','개인 아바타 제작에는 본인 동의가 필요합니다.','Enterprise의 API 한도는 별도 계약을 확인해야 합니다.'],array['https://www.synthesia.io/pricing','https://help.synthesia.io/en/articles/15972650-what-are-synthesia-s-pricing-plans'],now(),now()),
('Descript','텍스트를 수정하듯 영상·오디오를 편집하고 전사·음성 복제를 제공하는 도구 #영상편집 #오디오편집 #전사 #음성복제','Descript는 녹음된 음성의 전사문을 편집해 영상과 오디오를 수정하고 자막, 화면 녹화, 필러 제거, 음성 복제와 음질 개선을 제공하는 AI 편집기입니다.','https://www.descript.com/','https://www.descript.com/favicon.ico','Freemium','$0','무료 월 1시간 전사 · Creator 연간 결제 월 $12',array['Free는 월 1시간 전사와 720p 내보내기를 제공합니다.','Creator는 연간 결제 월 $12에 월 10시간 전사와 4K·무워터마크 내보내기를 제공합니다.','Pro는 연간 결제 월 $24에 월 30시간 전사와 확장 AI 기능을 제공합니다.'],'USD','https://www.descript.com/price',now(),'None',true,false,false,null,'Augmented','specialized',array['텍스트 기반 영상·오디오 편집','자동 전사·자막','음성 복제'],array['필러 제거','Studio Sound','화면 녹화'],array['전사문 수정으로 미디어 편집','팟캐스트·영상 작업 통합','자동 자막과 음질 개선'],array['팟캐스터와 영상 편집자','인터뷰·강의를 빠르게 편집하는 사용자'],array['무료 플랜의 전사와 내보내기 품질은 제한됩니다.','음성 복제에는 당사자의 동의가 필요합니다.','한국어 전사 품질은 실제 자료로 확인해야 합니다.'],array['https://www.descript.com/','https://www.descript.com/price'],now(),now()),
