('https://www.descript.com/','video-audio'),('https://lumalabs.ai/','video-audio'),('https://lumalabs.ai/','design-art'),
('https://www.capcut.com/tools/ai-tools','video-audio'),('https://gamma.app/','productivity'),
('https://www.notion.com/product/ai','productivity'),('https://www.notion.com/product/ai','writing-content'),
('https://lovable.dev/','development'),('https://replit.com/ai','development'),('https://windsurf.com/','development')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
